style.css:
@-moz-document domain("roblox.com") {
/* Background image (your cat pic) */
  body {
    background: url("https://i.imgur.com/qwiNU9M.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Old-style Robux icon top right (light pink) */
  .icon-robux,
  .rbx-navbar .rbx-robux .icon-robux {
    background-image: url("https://i.imgur.com/Bur2bsw.png") !important; /* pink 2016 robux icon */
    background-size: contain !important;
    filter: brightness(1.2);
  }

  /* Change "Play" button color (when entering a game) */
  .btn-common-play-game,
  .btn-primary-lg {
    background-color: #ffb6c1 !important; /* light pink */
    border-color: #ffb6c1 !important;
    color: #fff !important;
  }

  .btn-common-play-game:hover,
  .btn-primary-lg:hover {
    background-color: #ff9bb3 !important; /* slightly darker pink hover */
    border-color: #ff9bb3 !important;
  }
}
